text:
{{
  (() => {
    const documento = String(inpCpCedulaConductor.text || "").trim();
    const conductor = appsmith.store.cp_ui_conductor_estado_operativo;

    if (!documento) return "";

    if (!conductor?.conductor_id) {
      return "Complete los datos para registrar el conductor en el directorio.";
    }

    const fecha = conductor.fecha_vencimiento_licencia
      ? new Date(
          `${String(conductor.fecha_vencimiento_licencia).substring(0, 10)}T00:00:00`
        ).toLocaleDateString("es-CO")
      : "Sin registrar";

    const dias = Number(conductor.dias_vigencia_licencia);

    const vigencia = Number.isFinite(dias)
      ? dias < 0
        ? `Vencida hace ${Math.abs(dias)} ${
            Math.abs(dias) === 1 ? "día" : "días"
          }`
        : dias === 0
          ? "Vence hoy"
          : `${dias} ${dias === 1 ? "día vigente" : "días vigentes"}`
      : "Vigencia no determinada";

    const categoria =
      String(conductor.categoria_licencia || "").trim() || "Sin categoría";

    const alcance =
      String(conductor.alcance_habilitacion || "")
        .replaceAll("_", " ")
        .trim() || "No definido";

    return [
      `Licencia: ${conductor.numero_licencia || "Sin registrar"} · Categoría: ${categoria}`,
      `Vencimiento: ${fecha} · ${vigencia}`,
      `Alcance: ${alcance}`
    ].join("\n");
  })()
}}
